import{_ as s,o as e,c as n,a5 as i}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"84. 交叉编译","description":"The Little Book of C 中文版 — 84. 交叉编译","frontmatter":{"title":"84. 交叉编译","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","09-可移植与现代 C","中文"],"description":"The Little Book of C 中文版 — 84. 交叉编译","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":84,"sidebarWeight":84,"alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/084-Cross-Compilation","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/084-Cross-Compilation"},"headers":[],"relativePath":"posts/c教程/zh-CN/09-可移植与现代 C/084-Cross-Compilation.md","filePath":"posts/c教程/zh-CN/09-可移植与现代 C/084-Cross-Compilation.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/zh-CN/09-可移植与现代 C/084-Cross-Compilation.md"};function p(l,a,o,c,d,h){return e(),n("div",null,[...a[0]||(a[0]=[i(`<p>[English version](/posts/c教程/en-US/09-Portable and Modern C/084-Cross-Compilation)</p><p>交叉编译意味着在一台机器上构建程序，以便它在另一台机器上运行。如果您曾经在笔记本电脑上编译过 C 程序并将其部署到 Raspberry Pi、ESP32 板，甚至自定义 Linux 映像，那么您就已经完成了交叉编译。</p><p>对于系统程序员、嵌入式开发人员以及任何为多种架构或操作系统进行构建的人来说，这是一项基本技能。</p><h4 id="步骤1-什么是交叉编译器" tabindex="-1">步骤1.什么是交叉编译器？ <a class="header-anchor" href="#步骤1-什么是交叉编译器" aria-label="Permalink to &quot;步骤1.什么是交叉编译器？&quot;">​</a></h4><p>交叉编译器是为不同于主机平台的目标平台生成可执行文件的编译器。</p><table tabindex="0"><thead><tr><th>术语</th><th>意义</th></tr></thead><tbody><tr><td>主持人</td><td>您构建代码的系统</td></tr><tr><td>目标</td><td>程序将运行的系统</td></tr><tr><td>构建</td><td>构建编译器本身的系统（通常与主机相同）</td></tr></tbody></table><p>示例：您使用的是 macOS (x86_64)，并且想要针对 Raspberry Pi (ARM) 进行编译。您的工具链必须将 x86 指令转换为 ARM 指令。</p><h4 id="步骤-2-为什么要交叉编译" tabindex="-1">步骤 2. 为什么要交叉编译？ <a class="header-anchor" href="#步骤-2-为什么要交叉编译" aria-label="Permalink to &quot;步骤 2. 为什么要交叉编译？&quot;">​</a></h4><ul><li>将软件部署到嵌入式设备，无需直接在其上编译。</li><li>从一个工作站构建多种架构。</li><li>生成可移植的二进制文件（适用于 ARM、MIPS、RISC-V 等）。</li><li>为最小系统或容器准备静态二进制文件。</li></ul><p>交叉编译是嵌入式Linux、物联网和固件开发的基础。</p><h4 id="步骤-3-安装交叉编译器" tabindex="-1">步骤 3. 安装交叉编译器 <a class="header-anchor" href="#步骤-3-安装交叉编译器" aria-label="Permalink to &quot;步骤 3. 安装交叉编译器&quot;">​</a></h4><p>在 Linux 上，安装适合您的目标体系结构的工具链包。示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install gcc-arm-linux-gnueabihf</span></span>
<span class="line"><span>sudo apt install gcc-aarch64-linux-gnu</span></span>
<span class="line"><span>sudo apt install gcc-riscv64-linux-gnu</span></span></code></pre></div><p>每个工具链包含：</p><p>-<code>gcc</code>或者<code>clang</code>交叉编译器 -<code>as</code>（汇编器） -<code>ld</code>（链接器）</p><ul><li>目标系统头文件和库</li></ul><h4 id="步骤-4-验证目标" tabindex="-1">步骤 4. 验证目标 <a class="header-anchor" href="#步骤-4-验证目标" aria-label="Permalink to &quot;步骤 4. 验证目标&quot;">​</a></h4><p>检查编译器的目标三元组：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arm-linux-gnueabihf-gcc -v</span></span></code></pre></div><p>输出示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Target: arm-linux-gnueabihf</span></span></code></pre></div><p>三重编码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;architecture&gt;-&lt;vendor&gt;-&lt;OS&gt;-&lt;ABI&gt;</span></span></code></pre></div><p>例如：</p><p>-<code>x86_64-pc-linux-gnu</code> -<code>arm-none-eabi</code>（裸机，无操作系统） -<code>aarch64-linux-gnu</code></p><h4 id="步骤-5-针对另一个平台进行编译" tabindex="-1">步骤 5. 针对另一个平台进行编译 <a class="header-anchor" href="#步骤-5-针对另一个平台进行编译" aria-label="Permalink to &quot;步骤 5. 针对另一个平台进行编译&quot;">​</a></h4><p>小代码：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello from cross-compiled C!\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>为 ARM 编译：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arm-linux-gnueabihf-gcc hello.c -o hello_arm</span></span></code></pre></div><p>将其传输到您的 ARM 设备：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scp hello_arm user@raspberrypi.local:/home/user/</span></span></code></pre></div><p>然后在 Pi 上运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello_arm</span></span></code></pre></div><p>如果一切配置正确，您将看到：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello from cross-compiled C!</span></span></code></pre></div><h4 id="步骤-6-静态链接与动态链接" tabindex="-1">步骤 6. 静态链接与动态链接 <a class="header-anchor" href="#步骤-6-静态链接与动态链接" aria-label="Permalink to &quot;步骤 6. 静态链接与动态链接&quot;">​</a></h4><p>交叉编译时，您的目标系统可能没有相同的库。您可以将所有内容链接到一个二进制文件中：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arm-linux-gnueabihf-gcc -static hello.c -o hello_static</span></span></code></pre></div><p>即使目标缺少共享库，静态链接也可确保二进制文件运行，这对于最小或嵌入式系统很有用。</p><h4 id="步骤-7-使用-clang-进行交叉编译" tabindex="-1">步骤 7. 使用 Clang 进行交叉编译 <a class="header-anchor" href="#步骤-7-使用-clang-进行交叉编译" aria-label="Permalink to &quot;步骤 7. 使用 Clang 进行交叉编译&quot;">​</a></h4><p>Clang 通过以下方式简化了多目标构建<code>--target</code>和<code>--sysroot</code>选项：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>clang --target=aarch64-linux-gnu --sysroot=/path/to/sysroot hello.c -o hello_arm64</span></span></code></pre></div><p><code>--sysroot</code>指向模仿目标文件系统的目录，包含其标头和库。</p><h4 id="步骤-8-从-linux-构建-windows-或-macos" tabindex="-1">步骤 8. 从 Linux 构建 Windows 或 macOS <a class="header-anchor" href="#步骤-8-从-linux-构建-windows-或-macos" aria-label="Permalink to &quot;步骤 8. 从 Linux 构建 Windows 或 macOS&quot;">​</a></h4><p>您还可以跨操作系统交叉编译：</p><p>Linux→Windows：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install mingw-w64</span></span>
<span class="line"><span>x86_64-w64-mingw32-gcc hello.c -o hello.exe</span></span></code></pre></div><p>Linux → macOS：更复杂，通常需要带有 Apple SDK 的 Clang 或<code>osxcross</code>.</p><h4 id="步骤-9-使用-cmake-或-makefile-实现自动化" tabindex="-1">步骤 9. 使用 CMake 或 Makefile 实现自动化 <a class="header-anchor" href="#步骤-9-使用-cmake-或-makefile-实现自动化" aria-label="Permalink to &quot;步骤 9. 使用 CMake 或 Makefile 实现自动化&quot;">​</a></h4><p>CMake 使多平台构建变得容易。</p><p><code>toolchain-arm.cmake</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET(CMAKE_SYSTEM_NAME Linux)</span></span>
<span class="line"><span>SET(CMAKE_SYSTEM_PROCESSOR arm)</span></span>
<span class="line"><span>SET(CMAKE_C_COMPILER arm-linux-gnueabihf-gcc)</span></span></code></pre></div><p>然后：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmake -DCMAKE_TOOLCHAIN_FILE=toolchain-arm.cmake ..</span></span>
<span class="line"><span>make</span></span></code></pre></div><p>您的构建系统现在知道它正在针对 ARM 进行交叉编译。</p><h4 id="步骤-10-小代码-检测并打印目标架构" tabindex="-1">步骤 10. 小代码：检测并打印目标架构 <a class="header-anchor" href="#步骤-10-小代码-检测并打印目标架构" aria-label="Permalink to &quot;步骤 10. 小代码：检测并打印目标架构&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>#if defined(__x86_64__)</span></span>
<span class="line"><span>    printf(&quot;x86_64\\n&quot;);</span></span>
<span class="line"><span>#elif defined(__aarch64__)</span></span>
<span class="line"><span>    printf(&quot;ARM64\\n&quot;);</span></span>
<span class="line"><span>#elif defined(__arm__)</span></span>
<span class="line"><span>    printf(&quot;ARM 32-bit\\n&quot;);</span></span>
<span class="line"><span>#elif defined(__riscv)</span></span>
<span class="line"><span>    printf(&quot;RISC-V\\n&quot;);</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>    printf(&quot;Unknown architecture\\n&quot;);</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>针对不同的目标进行编译并观察输出。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>交叉编译将您的笔记本电脑连接到您将要编程的所有其他设备。这就是内核模块、嵌入式系统甚至 Android 应用程序的构建方式。一旦你学会了它，你就可以在任何地方、为任何东西进行构建。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>在主机系统上安装 ARM 或 RISC-V 交叉编译器。</li><li>在模拟器上交叉编译并运行一个简单的“Hello”二进制文件（<code>qemu-arm</code>).</li><li>使用<code>-static</code>标志以使其独立。</li><li>添加带有变量的 Makefile<code>CC</code>,<code>CFLAGS</code>， 和<code>LDFLAGS</code>以便于重复使用。</li><li>尝试从同一源构建 Linux 和 Windows。</li></ol><p>接下来，您将探索使用 pthread 的线程，以及如何使用标准 C 线程同时运行程序的多个部分。</p>`,64)])])}const g=s(t,[["render",p]]);export{u as __pageData,g as default};
